function LeatherEdgeBevelerMaker.init() LeatherEdgeBevelerMaker.ironStock=16; LeatherEdgeBevelerMaker.bronzeStock=14; LeatherEdgeBevelerMaker.woodStock=10; LeatherEdgeBevelerMaker.leatherStock=10; LeatherEdgeBevelerMaker.silverStock=8; LeatherEdgeBevelerMaker.goldStock=6; LeatherEdgeBevelerMaker.jewelStock=4; LeatherEdgeBevelerMaker.pearlStock=4; LeatherEdgeBevelerMaker.productStock={}; LeatherEdgeBevelerMaker.buildings={}; LeatherEdgeBevelerMaker.maker=nil; LeatherEdgeBevelerMaker.activeMaking={}; LeatherEdgeBevelerMaker.totalProducts=0; LeatherEdgeBevelerMaker.dayTimer=0; print("[LeatherEdgeBevelerMaker] Royal Leather Edge Beveler Maker System initialized (6 products, 4 buildings)") end
function LeatherEdgeBevelerMaker.hireMaker(n,s) s=s or math.random(55,90); local c=585+s*12; if not _G.state or (_G.state.gold or 0)<c then return false,"Premalo zlata" end; _G.state.gold=_G.state.gold-c; LeatherEdgeBevelerMaker.maker={name=n or ("Posevnik "..math.random(1,99)),skill=s,hiredDay=os.time(),itemsMade=0}; if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Posevnik najet: %s (spretnost: %d)",LeatherEdgeBevelerMaker.maker.name,s),"success") end; return true end
function LeatherEdgeBevelerMaker.canBuild(id) local d=BUILDINGS[id]; if not d then return false,"Neznana zgradba" end; if not _G.state then return false,"Brez stanja" end; if _G.state.gold<(d.cost.gold or 0) then return false,"Premalo zlata" end; if _G.state.resources then for r,a in pairs(d.cost) do if r~="gold" and (_G.state.resources[r] or 0)<a then return false,"Premalo "..r end end end; return true end
function LeatherEdgeBevelerMaker.build(id) local ok,e=LeatherEdgeBevelerMaker.canBuild(id); if not ok then return false,e end; local d=BUILDINGS[id]; _G.state.gold=_G.state.gold-(d.cost.gold or 0); if _G.state.resources then for r,a in pairs(d.cost) do if r~="gold" then _G.state.resources[r]=(_G.state.resources[r] or 0)-a end end end; table.insert(LeatherEdgeBevelerMaker.buildings,{type=id,builtDay=os.time()}); if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,"Zgrajeno: "..d.name,"success") end; return true end
function LeatherEdgeBevelerMaker.getQualityBonus() local b=0; for _,bd in ipairs(LeatherEdgeBevelerMaker.buildings) do local d=BUILDINGS[bd.type]; if d and d.qualityBonus then b=b+d.qualityBonus end end; return b end
function LeatherEdgeBevelerMaker.canMake(pt) local d=PRODUCTS[pt]; if not d then return false,"Neznan produkt" end; if d.ironCost and LeatherEdgeBevelerMaker.ironStock<(d.ironCost or 0) then return false,"Premalo železa" end; if d.bronzeCost and LeatherEdgeBevelerMaker.bronzeStock<(d.bronzeCost or 0) then return false,"Premalo brona" end; if d.woodCost and LeatherEdgeBevelerMaker.woodStock<(d.woodCost or 0) then return false,"Premalo lesa" end; if d.leatherCost and LeatherEdgeBevelerMaker.leatherStock<(d.leatherCost or 0) then return false,"Premalo usnja" end; if d.silverCost and LeatherEdgeBevelerMaker.silverStock<(d.silverCost or 0) then return false,"Premalo srebra" end; if d.goldCost and LeatherEdgeBevelerMaker.goldStock<(d.goldCost or 0) then return false,"Premalo zlata" end; if d.jewelCost and LeatherEdgeBevelerMaker.jewelStock<(d.jewelCost or 0) then return false,"Premalo draguljev" end; if d.pearlCost and LeatherEdgeBevelerMaker.pearlStock<(d.pearlCost or 0) then return false,"Premalo biserov" end; if #LeatherEdgeBevelerMaker.buildings==0 then return false,"Potrebna posevna delavnica" end; if not LeatherEdgeBevelerMaker.maker then return false,"Potreben posevnik" end; return true end
function LeatherEdgeBevelerMaker.make(pt,qty) qty=qty or 1; local ok,e=LeatherEdgeBevelerMaker.canMake(pt); if not ok then return false,e end; local d=PRODUCTS[pt]; if d.ironCost then LeatherEdgeBevelerMaker.ironStock=LeatherEdgeBevelerMaker.ironStock-d.ironCost*qty end; if d.bronzeCost then LeatherEdgeBevelerMaker.bronzeStock=LeatherEdgeBevelerMaker.bronzeStock-d.bronzeCost*qty end; if d.woodCost then LeatherEdgeBevelerMaker.woodStock=LeatherEdgeBevelerMaker.woodStock-d.woodCost*qty end; if d.leatherCost then LeatherEdgeBevelerMaker.leatherStock=LeatherEdgeBevelerMaker.leatherStock-d.leatherCost*qty end; if d.silverCost then LeatherEdgeBevelerMaker.silverStock=LeatherEdgeBevelerMaker.silverStock-d.silverCost*qty end; if d.goldCost then LeatherEdgeBevelerMaker.goldStock=LeatherEdgeBevelerMaker.goldStock-d.goldCost*qty end; if d.jewelCost then LeatherEdgeBevelerMaker.jewelStock=LeatherEdgeBevelerMaker.jewelStock-d.jewelCost*qty end; if d.pearlCost then LeatherEdgeBevelerMaker.pearlStock=LeatherEdgeBevelerMaker.pearlStock-d.pearlCost*qty end; local t=d.time; if LeatherEdgeBevelerMaker.maker then t=math.max(1,t-math.floor(LeatherEdgeBevelerMaker.maker.skill/13)) end; table.insert(LeatherEdgeBevelerMaker.activeMaking,{id="leatheredgebeveler_"..tostring(os.time()).."_"..tostring(math.random(1000,9999)),productType=pt,productName=d.name,cost=d.cost*qty,quantity=qty,food=0,prestige=d.prestige or 0,happiness=d.happiness or 0,daysRemaining=t,started=os.time()}); if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Izdelava: %d %s (%d dni)",qty,d.name,t),"info") end; return true end
function LeatherEdgeBevelerMaker.completeMaking(m) local q=1.0+(LeatherEdgeBevelerMaker.getQualityBonus()/100); if LeatherEdgeBevelerMaker.maker then q=q+(LeatherEdgeBevelerMaker.maker.skill/140) end; q=math.min(2.5,q); LeatherEdgeBevelerMaker.productStock[m.productType]=(LeatherEdgeBevelerMaker.productStock[m.productType] or 0)+m.quantity; LeatherEdgeBevelerMaker.totalProducts=LeatherEdgeBevelerMaker.totalProducts+m.quantity; if m.prestige>0 and _G.state and _G.state.happiness then _G.state.happiness=math.min(100,_G.state.happiness+m.prestige) end; if m.happiness>0 and _G.state and _G.state.happiness then _G.state.happiness=math.min(100,_G.state.happiness+m.happiness) end; if LeatherEdgeBevelerMaker.maker then LeatherEdgeBevelerMaker.maker.itemsMade=LeatherEdgeBevelerMaker.maker.itemsMade+m.quantity; if math.random()<0.25 then LeatherEdgeBevelerMaker.maker.skill=math.min(100,LeatherEdgeBevelerMaker.maker.skill+1) end end; if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Posevnik izdelan: %d %s (kakovost: %.1f)",m.quantity,m.productName,q),"success") end; if _G.GameEventBus then pcall(_G.GameEventBus.publish,"leatheredgebeveler.completed",{productName=m.productName,prestige=m.prestige,happiness=m.happiness}) end end
function LeatherEdgeBevelerMaker.update(dt) if not _G.state then return end; LeatherEdgeBevelerMaker.dayTimer=LeatherEdgeBevelerMaker.dayTimer+dt; if LeatherEdgeBevelerMaker.dayTimer>=30 then LeatherEdgeBevelerMaker.dayTimer=0; for i=#LeatherEdgeBevelerMaker.activeMaking,1,-1 do local m=LeatherEdgeBevelerMaker.activeMaking[i]; m.daysRemaining=m.daysRemaining-1; if m.daysRemaining<=0 then LeatherEdgeBevelerMaker.completeMaking(m); table.remove(LeatherEdgeBevelerMaker.activeMaking,i) end end; local tu=0; for _,bd in ipairs(LeatherEdgeBevelerMaker.buildings) do local d=BUILDINGS[bd.type]; if d and d.upkeep then tu=tu+d.upkeep end end; if LeatherEdgeBevelerMaker.maker then tu=tu+15 end; if tu>0 and _G.state then _G.state.gold=math.max(0,(_G.state.gold or 0)-tu) end end end
function LeatherEdgeBevelerMaker.getStats() return {ironStock=LeatherEdgeBevelerMaker.ironStock,bronzeStock=LeatherEdgeBevelerMaker.bronzeStock,woodStock=LeatherEdgeBevelerMaker.woodStock,leatherStock=LeatherEdgeBevelerMaker.leatherStock,silverStock=LeatherEdgeBevelerMaker.silverStock,goldStock=LeatherEdgeBevelerMaker.goldStock,jewelStock=LeatherEdgeBevelerMaker.jewelStock,pearlStock=LeatherEdgeBevelerMaker.pearlStock,productStock=LeatherEdgeBevelerMaker.productStock,numBuildings=#LeatherEdgeBevelerMaker.buildings,hasMaker=LeatherEdgeBevelerMaker.maker~=nil,makerName=LeatherEdgeBevelerMaker.maker and LeatherEdgeBevelerMaker.maker.name or "—",makerSkill=LeatherEdgeBevelerMaker.maker and LeatherEdgeBevelerMaker.maker.skill or 0,activeMaking=#LeatherEdgeBevelerMaker.activeMaking,totalProducts=LeatherEdgeBevelerMaker.totalProducts} end
